--------------------------------------------------------
--  DDL for View VW_CXP_ANTIGUEDAD_SALDOS
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTOANALISIS"."VW_CXP_ANTIGUEDAD_SALDOS" ("ID_DOCUMENTO", "ID_PROVEEDOR", "NIT_PROVEEDOR", "PROVEEDOR", "TIPO_DOCUMENTO", "SERIE", "NUMERO_DOCUMENTO", "FECHA_DOCUMENTO", "FECHA_VENCIMIENTO", "MONEDA", "TOTAL_NETO", "SALDO_PENDIENTE", "DIAS_VENCIDO", "RANGO_ANTIGUEDAD", "PRIORIDAD", "ESTADO") AS 
  SELECT
    D.ID_DOCUMENTO,
    D.ID_PROVEEDOR,
    D.NIT_EMISOR AS NIT_PROVEEDOR,
    CAST(NULL AS VARCHAR2(150)) AS PROVEEDOR,
    D.TIPO_DOCUMENTO,
    D.SERIE,
    D.NUMERO_DOCUMENTO,
    D.FECHA_DOCUMENTO,
    D.FECHA_VENCIMIENTO,
    D.MONEDA,
    D.TOTAL_NETO,
    D.SALDO_PENDIENTE,
    GREATEST(TRUNC(SYSDATE) - TRUNC(D.FECHA_VENCIMIENTO), 0)
        AS DIAS_VENCIDO,
    CASE
        WHEN D.FECHA_VENCIMIENTO >= TRUNC(SYSDATE) THEN 'POR_VENCER'
        WHEN TRUNC(SYSDATE) - TRUNC(D.FECHA_VENCIMIENTO) <= 30 THEN '1_30'
        WHEN TRUNC(SYSDATE) - TRUNC(D.FECHA_VENCIMIENTO) <= 60 THEN '31_60'
        WHEN TRUNC(SYSDATE) - TRUNC(D.FECHA_VENCIMIENTO) <= 90 THEN '61_90'
        ELSE 'MAS_90'
    END AS RANGO_ANTIGUEDAD,
    D.PRIORIDAD,
    D.ESTADO
FROM "PROYECTOANALISIS"."CXP_DOCUMENTO" D
WHERE D.NATURALEZA = 'D'
  AND D.SALDO_PENDIENTE > 0
  AND D.FECHA_VENCIMIENTO IS NOT NULL
  AND D.ESTADO IN ('APROBADA', 'CONTABILIZADA', 'PENDIENTE_PAGO',
                   'PROGRAMADA_PAGO', 'PARCIALMENTE_PAGADA', 'VENCIDA',
                   'BLOQUEADA', 'EN_DISPUTA')
;
--------------------------------------------------------
--  DDL for View VW_CXP_CUENTAS_COMPARTIDAS
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTOANALISIS"."VW_CXP_CUENTAS_COMPARTIDAS" ("BANCO_NOMBRE", "NUMERO_CUENTA", "MONEDA", "CANTIDAD_PROVEEDORES", "IDS_PROVEEDORES") AS 
  SELECT
    C.BANCO_NOMBRE,
    C.NUMERO_CUENTA,
    C.MONEDA,
    COUNT(DISTINCT C.ID_PROVEEDOR) AS CANTIDAD_PROVEEDORES,
    LISTAGG(TO_CHAR(C.ID_PROVEEDOR), ', ')
        WITHIN GROUP (ORDER BY C.ID_PROVEEDOR) AS IDS_PROVEEDORES
FROM "PROYECTOANALISIS"."CXP_CUENTA_BANCARIA" C
WHERE C.TIPO_TITULAR = 'PROVEEDOR'
  AND C.ESTADO = 'ACTIVA'
GROUP BY C.BANCO_NOMBRE, C.NUMERO_CUENTA, C.MONEDA
HAVING COUNT(DISTINCT C.ID_PROVEEDOR) > 1
;
--------------------------------------------------------
--  DDL for View VW_CXP_DASHBOARD
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTOANALISIS"."VW_CXP_DASHBOARD" ("MONEDA", "TOTAL_PENDIENTE", "TOTAL_VENCIDO", "VENCE_EN_7_DIAS", "DOCUMENTOS_PEND_APROBACION", "DOCUMENTOS_EN_DISPUTA", "DOCUMENTOS_BLOQUEADOS", "PAGOS_PROGRAMADOS", "ANTICIPOS_SIN_APLICAR") AS 
  SELECT
    D.MONEDA,
    SUM(D.SALDO_PENDIENTE) AS TOTAL_PENDIENTE,
    SUM(CASE
            WHEN D.FECHA_VENCIMIENTO < TRUNC(SYSDATE)
            THEN D.SALDO_PENDIENTE ELSE 0
        END) AS TOTAL_VENCIDO,
    SUM(CASE
            WHEN D.FECHA_VENCIMIENTO BETWEEN TRUNC(SYSDATE)
                 AND TRUNC(SYSDATE) + 7
            THEN D.SALDO_PENDIENTE ELSE 0
        END) AS VENCE_EN_7_DIAS,
    SUM(CASE WHEN D.ESTADO = 'PENDIENTE_APROBACION' THEN 1 ELSE 0 END)
        AS DOCUMENTOS_PEND_APROBACION,
    SUM(CASE WHEN D.ESTADO = 'EN_DISPUTA' THEN 1 ELSE 0 END)
        AS DOCUMENTOS_EN_DISPUTA,
    SUM(CASE WHEN D.ESTADO = 'BLOQUEADA' THEN 1 ELSE 0 END)
        AS DOCUMENTOS_BLOQUEADOS,
    (SELECT NVL(SUM(P.MONTO_OBLIGACION), 0)
       FROM "PROYECTOANALISIS"."CXP_PAGO" P
      WHERE P.MONEDA = D.MONEDA
        AND P.ESTADO IN ('PROGRAMADO', 'PENDIENTE_APROBACION', 'APROBADO'))
        AS PAGOS_PROGRAMADOS,
    (SELECT NVL(SUM(P.MONTO_NO_APLICADO), 0)
       FROM "PROYECTOANALISIS"."CXP_PAGO" P
      WHERE P.MONEDA = D.MONEDA
        AND P.TIPO_PAGO = 'ANTICIPO'
        AND P.ESTADO NOT IN ('ANULADO', 'DEVUELTO', 'RECHAZADO'))
        AS ANTICIPOS_SIN_APLICAR
FROM "PROYECTOANALISIS"."CXP_DOCUMENTO" D
WHERE D.NATURALEZA = 'D'
  AND D.ESTADO NOT IN ('DUPLICADO', 'RECHAZADA', 'ANULADA', 'CERRADA')
GROUP BY D.MONEDA
;
--------------------------------------------------------
--  DDL for View VW_CXP_ESTADO_CUENTA
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTOANALISIS"."VW_CXP_ESTADO_CUENTA" ("ID_PROVEEDOR", "FECHA_MOVIMIENTO", "TIPO_MOVIMIENTO", "ID_ORIGEN", "REFERENCIA", "DEBITO", "CREDITO", "MONEDA", "ESTADO") AS 
  SELECT
    D.ID_PROVEEDOR,
    CAST(D.FECHA_DOCUMENTO AS TIMESTAMP) AS FECHA_MOVIMIENTO,
    D.TIPO_DOCUMENTO AS TIPO_MOVIMIENTO,
    D.ID_DOCUMENTO AS ID_ORIGEN,
    NVL(D.SERIE || '-', '') || D.NUMERO_DOCUMENTO AS REFERENCIA,
    CASE WHEN D.NATURALEZA = 'D' THEN D.TOTAL_NETO ELSE 0 END AS DEBITO,
    CASE WHEN D.NATURALEZA = 'C' THEN D.TOTAL_NETO ELSE 0 END AS CREDITO,
    D.MONEDA,
    D.ESTADO
FROM "PROYECTOANALISIS"."CXP_DOCUMENTO" D
WHERE D.ID_PROVEEDOR IS NOT NULL
UNION ALL
SELECT
    P.ID_PROVEEDOR,
    NVL(P.FECHA_PAGO, CAST(P.FECHA_PROGRAMADA AS TIMESTAMP)),
    'PAGO_' || P.TIPO_PAGO,
    P.ID_PAGO,
    P.CODIGO_PAGO,
    0,
    P.MONTO_OBLIGACION,
    P.MONEDA,
    P.ESTADO
FROM "PROYECTOANALISIS"."CXP_PAGO" P
WHERE P.ESTADO NOT IN ('BORRADOR', 'RECHAZADO', 'DEVUELTO', 'ANULADO')
;
--------------------------------------------------------
--  DDL for View VW_CXP_INTEGRACION_COMPRAS
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTOANALISIS"."VW_CXP_INTEGRACION_COMPRAS" ("ID_DOCUMENTO", "NO_FACTURA_COMPRA", "FAC_FECHA_FACTURA", "ID_PROVEEDOR", "PRO_NIT", "PRO_NOMBRE_ENTIDAD", "NO_ORDEN_COMPRA", "OCO_FECHA_EMISION", "NO_RECEPCION", "RBO_FECHA_RECEPCION", "TOTAL_COMPRAS", "TOTAL_CXP", "DIFERENCIA_INTEGRACION", "RESULTADO_TRES_VIAS", "ESTADO") AS 
  SELECT
    D.ID_DOCUMENTO,
    D.NO_FACTURA_COMPRA,
    F.FAC_FECHA_FACTURA,
    D.ID_PROVEEDOR,
    D.NIT_EMISOR AS PRO_NIT,
    CAST(NULL AS VARCHAR2(150)) AS PRO_NOMBRE_ENTIDAD,
    D.NO_ORDEN_COMPRA,
    O.OCO_FECHA_EMISION,
    D.NO_RECEPCION,
    R.RBO_FECHA_RECEPCION,
    F.FAC_TOTAL_FACTURA AS TOTAL_COMPRAS,
    D.TOTAL_BRUTO AS TOTAL_CXP,
    D.TOTAL_BRUTO - F.FAC_TOTAL_FACTURA AS DIFERENCIA_INTEGRACION,
    D.RESULTADO_TRES_VIAS,
    D.ESTADO
FROM "PROYECTOANALISIS"."CXP_DOCUMENTO" D
JOIN "PROYECTOANALISIS"."CMP_FACTURA_CXP" F
  ON F.FAC_NO_FACTURA = D.NO_FACTURA_COMPRA
LEFT JOIN "PROYECTOANALISIS"."CMP_ORDEN_COMPRA" O
  ON O.OCO_NO_PO = D.NO_ORDEN_COMPRA
LEFT JOIN "PROYECTOANALISIS"."CMP_RECEPCION_BODEGA" R
  ON R.RBO_NO_RECEPCION = D.NO_RECEPCION
;
--------------------------------------------------------
--  DDL for View VW_CXP_VALIDACION_TRES_VIAS
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTOANALISIS"."VW_CXP_VALIDACION_TRES_VIAS" ("ID_DOCUMENTO", "NUMERO_DOCUMENTO", "NO_ORDEN_COMPRA", "NO_RECEPCION", "NUMERO_LINEA", "CODIGO_ARTICULO", "DESCRIPCION", "CANTIDAD_ORDENADA", "CANTIDAD_RECIBIDA", "CANTIDAD_FACTURADA", "PRECIO_ORDENADO", "PRECIO_FACTURADO", "DIFERENCIA_CANTIDAD", "DIFERENCIA_PRECIO", "RESULTADO_TRES_VIAS") AS 
  SELECT
    D.ID_DOCUMENTO,
    D.NUMERO_DOCUMENTO,
    D.NO_ORDEN_COMPRA,
    D.NO_RECEPCION,
    L.NUMERO_LINEA,
    L.CODIGO_ARTICULO,
    L.DESCRIPCION,
    L.CANTIDAD_ORDENADA,
    L.CANTIDAD_RECIBIDA,
    L.CANTIDAD_FACTURADA,
    L.PRECIO_ORDENADO,
    L.PRECIO_FACTURADO,
    L.DIFERENCIA_CANTIDAD,
    L.DIFERENCIA_PRECIO,
    L.RESULTADO_TRES_VIAS
FROM "PROYECTOANALISIS"."CXP_DOCUMENTO" D
JOIN "PROYECTOANALISIS"."CXP_DOCUMENTO_DETALLE" L
  ON L.ID_DOCUMENTO = D.ID_DOCUMENTO
WHERE D.TIPO_REGISTRO = 'CON_OC'
;
