  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_TIPO" CHECK (TIPO_DOCUMENTO IN ('FACTURA', 'FACTURA_CAMBIARIA', 'NOTA_CREDITO',
                            'NOTA_DEBITO', 'RECIBO', 'REEMBOLSO',
                            'LIQUIDACION_VIATICO', 'GASTO_CAJA_CHICA',
                            'CUOTA_CONTRATO', 'CUOTA_PRESTAMO',
                            'OBLIGACION_FISCAL', 'SALDO_INICIAL',
                            'COMPROBANTE_SERVICIO', 'OTRO')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_NAT" CHECK (NATURALEZA IN ('D', 'C')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_ORIGEN" CHECK (ORIGEN_INGRESO IN ('MANUAL', 'ARCHIVO', 'CORREO', 'IMPORTACION',
                            'COMPRAS', 'CARGA_MASIVA', 'INTEGRACION',
                            'PORTAL_PROVEEDOR', 'FACTURACION_ELECTRONICA')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_REGISTRO" CHECK (TIPO_REGISTRO IN ('CON_OC', 'SIN_OC', 'RECURRENTE',
                           'SALDO_INICIAL', 'IMPORTADO')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_OC_REQ" CHECK (TIPO_REGISTRO <> 'CON_OC' OR NO_ORDEN_COMPRA IS NOT NULL) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_COMPRA_REQ" CHECK (ORIGEN_INGRESO <> 'COMPRAS' OR NO_FACTURA_COMPRA IS NOT NULL) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_MONEDA" CHECK (LENGTH(MONEDA) = 3 AND TIPO_CAMBIO > 0) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_MONTOS" CHECK (
        SUBTOTAL >= 0 AND DESCUENTO_TOTAL >= 0 AND IMPUESTO_TOTAL >= 0
        AND RETENCION_TOTAL >= 0 AND RECARGO_TOTAL >= 0
        AND GASTO_ADICIONAL_TOTAL >= 0 AND TOTAL_BRUTO >= 0
        AND TOTAL_NETO >= 0 AND TOTAL_LOCAL >= 0 AND MONTO_APLICADO >= 0
        AND SALDO_PENDIENTE >= 0 AND MONTO_APLICADO <= TOTAL_NETO
        AND CAPITAL_CUOTA >= 0 AND INTERES_CUOTA >= 0 AND COMISION_CUOTA >= 0
    ) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_CALCULO" CHECK (
        TOTAL_BRUTO = ROUND(
            SUBTOTAL - DESCUENTO_TOTAL + IMPUESTO_TOTAL + RECARGO_TOTAL
            + GASTO_ADICIONAL_TOTAL + DIFERENCIA_REDONDEO,
            2
        )
        AND TOTAL_NETO = ROUND(TOTAL_BRUTO - RETENCION_TOTAL, 2)
        AND SALDO_PENDIENTE = ROUND(TOTAL_NETO - MONTO_APLICADO, 2)
        AND ABS(TOTAL_LOCAL - ROUND(TOTAL_NETO * TIPO_CAMBIO, 2)) <= 0.01
    ) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_TRES_VIAS" CHECK (RESULTADO_TRES_VIAS IN ('NO_APLICA', 'COINCIDE', 'DENTRO_TOLERANCIA',
                                 'DIFERENCIA', 'DIF_PRECIO', 'DIF_CANTIDAD',
                                 'NO_RECIBIDO', 'SUPERA_ORDEN', 'SIN_RECEPCION',
                                 'ORDEN_CERRADA', 'ORDEN_ANULADA',
                                 'EN_INVESTIGACION', 'DIFERENCIA_APROBADA',
                                 'BLOQUEADO')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_PRIORIDAD" CHECK (PRIORIDAD IN ('CRITICA', 'ALTA', 'NORMAL', 'BAJA')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_CONTABLE" CHECK (ESTADO_CONTABLE IN ('PENDIENTE', 'ENVIADO', 'CONTABILIZADO',
                             'ERROR', 'REVERTIDO', 'NO_APLICA')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_DUP" CHECK (POSIBLE_DUPLICADO IN ('S', 'N')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_ESTADO" CHECK (ESTADO IN ('RECIBIDO', 'PENDIENTE_CLASIFICACION', 'BORRADOR',
                    'PENDIENTE_REVISION', 'EN_VALIDACION', 'DUPLICADO',
                    'CON_DIFERENCIAS', 'PENDIENTE_APROBACION', 'APROBADA',
                    'RECHAZADA', 'CONTABILIZADA', 'PENDIENTE_PAGO',
                    'PROGRAMADA_PAGO', 'PARCIALMENTE_PAGADA', 'PAGADA',
                    'VENCIDA', 'BLOQUEADA', 'EN_DISPUTA',
                    'PARCIALMENTE_APLICADA', 'APLICADA', 'ANULADA', 'CERRADA')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_RECHAZO" CHECK (ESTADO <> 'RECHAZADA' OR MOTIVO_RECHAZO IS NOT NULL) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_BLOQUEO" CHECK (ESTADO <> 'BLOQUEADA' OR MOTIVO_BLOQUEO IS NOT NULL) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_ANULACION" CHECK (
