        OR ESTADO <> 'ANULADA'
    ) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_DOCUMENTO" ADD CONSTRAINT "CK_CXP_DOC_REL_DIST" CHECK (ID_DOCUMENTO_RELACIONADO IS NULL
         OR ID_DOCUMENTO_RELACIONADO <> ID_DOCUMENTO) ENABLE;
