  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_TIPO" CHECK (TIPO_PAGO IN ('ORDINARIO', 'ANTICIPO', 'REEMBOLSO',
                       'REPOSICION_CAJA', 'DEVOLUCION', 'REVERSO',
                       'COMPENSACION')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_MONEDA" CHECK (LENGTH(MONEDA) = 3 AND TIPO_CAMBIO > 0) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_MONTOS" CHECK (
        MONTO_OBLIGACION > 0 AND MONTO_DESCUENTO >= 0
        AND MONTO_RETENCION >= 0 AND MONTO_COMISION >= 0
        AND MONTO_TRANSFERIDO >= 0 AND MONTO_APLICADO >= 0
        AND MONTO_NO_APLICADO >= 0 AND MONTO_APLICADO <= MONTO_OBLIGACION
        AND MONTO_TRANSFERIDO = ROUND(
            MONTO_OBLIGACION - MONTO_DESCUENTO - MONTO_RETENCION
            + MONTO_COMISION,
            2
        )
        AND MONTO_NO_APLICADO = ROUND(MONTO_OBLIGACION - MONTO_APLICADO, 2)
    ) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_REVERSA" CHECK (TIPO_PAGO NOT IN ('DEVOLUCION', 'REVERSO') OR ID_PAGO_ORIGEN IS NOT NULL) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_CONTABLE" CHECK (ESTADO_CONTABLE IN ('PENDIENTE', 'ENVIADO', 'CONTABILIZADO',
                             'ERROR', 'REVERTIDO', 'NO_APLICA')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_ESTADO" CHECK (ESTADO IN ('BORRADOR', 'PROGRAMADO', 'PENDIENTE_APROBACION',
                    'APROBADO', 'ENVIADO', 'EN_PROCESO', 'EJECUTADO',
                    'CONFIRMADO', 'PARCIALMENTE_APLICADO', 'APLICADO',
                    'CONCILIADO', 'RECHAZADO', 'DEVUELTO', 'ANULADO')) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_RECHAZO" CHECK (ESTADO <> 'RECHAZADO' OR MOTIVO_RECHAZO IS NOT NULL) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_DEV" CHECK (ESTADO <> 'DEVUELTO' OR MOTIVO_DEVOLUCION IS NOT NULL) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_ANUL" CHECK (ESTADO <> 'ANULADO' OR MOTIVO_ANULACION IS NOT NULL) ENABLE;
  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_SOD" CHECK (
        (EJECUTADO_POR IS NULL OR EJECUTADO_POR <> PROGRAMADO_POR)
        AND (CONCILIADO_POR IS NULL OR CONCILIADO_POR <> PROGRAMADO_POR)
        AND (CONCILIADO_POR IS NULL OR EJECUTADO_POR IS NULL
             OR CONCILIADO_POR <> EJECUTADO_POR)
    ) ENABLE;
