  ALTER TABLE "PROYECTOANALISIS"."CXP_PAGO" ADD CONSTRAINT "CK_CXP_PAGO_EJEC" CHECK (
        (ESTADO IN ('EJECUTADO', 'CONFIRMADO', 'PARCIALMENTE_APLICADO',
                    'APLICADO', 'CONCILIADO')
         AND EJECUTADO_POR IS NOT NULL AND FECHA_PAGO IS NOT NULL)
        OR ESTADO NOT IN ('EJECUTADO', 'CONFIRMADO',
                          'PARCIALMENTE_APLICADO', 'APLICADO', 'CONCILIADO')
    ) ENABLE;
