         AND ID_DOCUMENTO_CXC IS NULL)
        OR
        (TIPO_APLICACION IN ('NOTA_CREDITO', 'AJUSTE')
         AND ID_PAGO IS NULL AND ID_DOCUMENTO_ORIGEN IS NOT NULL
         AND ID_DOCUMENTO_CXC IS NULL)
        OR
        (TIPO_APLICACION = 'COMPENSACION_CXC'
         AND ID_PAGO IS NULL AND ID_DOCUMENTO_ORIGEN IS NULL
         AND ID_DOCUMENTO_CXC IS NOT NULL)
    ) ENABLE;
